expr:
(
  (
    smartctl_device_critical_warning{job=~"smartctl|prometheus-smartctl-prometheus-smartctl-exporter"} > 0
    and
    smartctl_device_critical_warning{job=~"smartctl|prometheus-smartctl-prometheus-smartctl-exporter"} != 4
  )
  * on(instance,device) group_left(serial_number) smartctl_device{job=~"smartctl|prometheus-smartctl-prometheus-smartctl-exporter"}
)
or
(
  smartctl_device_smart_status{job=~"smartctl|prometheus-smartctl-prometheus-smartctl-exporter"} == 0
  and on(instance,device) smartctl_device{job=~"smartctl|prometheus-smartctl-prometheus-smartctl-exporter",protocol!="NVMe"}
)

(
  count by (instance,job) (up{job=~"smartctl|prometheus-smartctl-prometheus-smartctl-exporter"} == 1)
)
unless on(instance,job) (
  count by (instance,job) (smartctl_device_smart_status{job=~"smartctl|prometheus-smartctl-prometheus-smartctl-exporter"})
)

time() - max by(namespace, job_name, cluster) (kube_job_status_start_time{namespace=~"(openshift-.*|kube-.*|default)",job="kube-state-metrics"}
  and
kube_job_status_active{namespace=~"(openshift-.*|kube-.*|default)",job="kube-state-metrics"} > 0) > 43200

sum by (namespace, pod, cluster) (
  max by(namespace, pod, cluster) (
    kube_pod_status_phase{namespace=~"(openshift-.*|kube-.*|default)", job="kube-state-metrics", phase=~"Pending|Unknown"}
    unless ignoring(phase) (kube_pod_status_unschedulable{job="kube-state-metrics"} == 1)
  ) * on(namespace, pod, cluster) group_left(owner_kind) topk by(namespace, pod, cluster) (
    1, max by(namespace, pod, owner_kind, cluster) (kube_pod_owner{owner_kind!="Job"})
  )
) > 0

sum by (namespace, pod) (
  max by(namespace, pod) (
    kube_pod_status_phase{namespace=~"(openshift-.*|kube-.*|default|logging)",job="kube-state-metrics", phase=~"Pending|Unknown"}
  ) * on(namespace, pod) group_left(owner_kind) topk by(namespace, pod) (
    1, max by(namespace, pod, owner_kind) (kube_pod_owner{owner_kind!="Job"})
  )
) > 0

node_filesystem_avail_bytes{
  namespace="royal-road",
  job="node-exporter",
  instance="host-db",
  device="/dev/md2",
  mountpoint="/",
  fstype="ext4"
} < 200 * 1024 * 1024 * 1024

# container=~ filter intentionally dropped: the Snuba consumers
# run container "sentry-snuba", taskworkers "taskworker", etc.;
# any restart burst on an ingestion pod matters. Threshold 2
# (was 3) because CrashLoopBackOff caps its backoff at 5m, so a
# dead-loop yields exactly ~3 restarts/15m and slipped past >3.
# Suppressed while kafka itself flaps: consumers exit fatally on
# broker connection loss, so every planned or spontaneous broker
# restart otherwise pages as ~11 concurrent "consumer crash
# loops". The SentryKafkaBroker* alerts below fire instead; a
# consumer loop that outlives the blip re-pages once it ages out
# of the window. The 25m blip lookback deliberately exceeds the
# consumer [15m] window so suppression cannot lapse mid-tail and
# re-page a dead storm.
sum by (namespace, pod) (
  increase(kube_pod_container_status_restarts_total{
    namespace="sentry",
    pod=~"sentry-(snuba-.*|issue-occurrence-consumer|post-process-forward-.*|ingest-.*|taskworker-ingest|relay|web)-.*"
  }[15m])
) > 2
unless on (namespace) (
  (
    min_over_time(kube_statefulset_status_replicas_ready{
      namespace="sentry",
      statefulset="kafka"
    }[25m]) == 0
  )
  or
  sum by (namespace) (
    increase(kube_pod_container_status_restarts_total{
      namespace="sentry",
      pod="kafka-0"
    }[25m])
  ) > 0
)

# Persistent partial shortfall (stuck rollout, unschedulable pod).
# HPA-scaled deployments are excluded: during sustained scale-up
# available < spec is normal, and a pod that never becomes ready
# there still shows up as CrashLooping or as a stuck HPA.
(
  kube_deployment_status_replicas_available{
    namespace="sentry",
    deployment=~"sentry-(snuba-.*|issue-occurrence-consumer|post-process-forward-.*|ingest-.*|taskworker-ingest|relay|web)"
  }
  <
  kube_deployment_spec_replicas{
    namespace="sentry",
    deployment=~"sentry-(snuba-.*|issue-occurrence-consumer|post-process-forward-.*|ingest-.*|taskworker-ingest|relay|web)"
  }
)
unless on (namespace, deployment)
label_replace(
  kube_horizontalpodautoscaler_info{namespace="sentry", scaletargetref_kind="Deployment"},
  "deployment", "$1", "scaletargetref_name", "(.*)"
)

# Covers every ingestion-path workload, not just the three
# original taskworker-era deployments. The 2026-09-27 outage
# happened with the three named deployments all healthy:
# the dead components were sentry-snuba-* consumers.
# Fires only when a deployment has NO available replica. The old
# "available < spec" form flapped 66x in 3 days on HPA-driven
# sentry-taskworker-ingest scale-ups (2026-11-12); partial
# shortfalls are SentryConsumerDegraded below.
kube_deployment_status_replicas_available{
  namespace="sentry",
  deployment=~"sentry-(snuba-.*|issue-occurrence-consumer|post-process-forward-.*|ingest-.*|taskworker-ingest|relay|web)"
} == 0
and
kube_deployment_spec_replicas{
  namespace="sentry",
  deployment=~"sentry-(snuba-.*|issue-occurrence-consumer|post-process-forward-.*|ingest-.*|taskworker-ingest|relay|web)"
} > 0

sum(increase(sentry_events_processed{
  job="statsd-exporter-prometheus-statsd-exporter"
}[15m])) == 0
# Also fire if the series disappears entirely (exporter restart
# loses the counter, or statsd stops receiving): == 0 alone
# returns nothing on an empty vector and would never fire.
or
absent_over_time(sentry_events_processed{
  job="statsd-exporter-prometheus-statsd-exporter"
}[15m])

# Guards the suppression blind spot: a kafka stuck crash-looping
# keeps the restart-blip window permanently true, so consumer-side
# alerts stay suppressed for the whole outage. This rule is the
# page for that case (StatefulSet, so the deployment-based
# SentryConsumerUnavailable cannot see it).
kube_statefulset_status_replicas_ready{
  namespace="sentry",
  statefulset="kafka"
}
<
kube_statefulset_replicas{
  namespace="sentry",
  statefulset="kafka"
}

# Root-cause companion to the SentryConsumerCrashLooping
# suppression: the broker blip itself pages here once, instead
# of as one alert per consumer pod. Both signals needed: the
# ready-count dip catches pod recreation (restarts_total resets
# on a new pod and misses it), the restarts blip catches fast
# in-pod restarts that fall between scrapes.
(
  min_over_time(kube_statefulset_status_replicas_ready{
    namespace="sentry",
    statefulset="kafka"
  }[25m]) == 0
)
or
sum by (namespace) (
  increase(kube_pod_container_status_restarts_total{
    namespace="sentry",
    pod="kafka-0"
  }[25m])
) > 0
